hints.code_snippet:
class GameItem {
    constructor(id, name, type, iconUrl) {
        this.id = id;
        this.name = name;
        this.type = type;
        this.iconUrl = iconUrl; // Still storing display-specific data in GameItem
    }

    getInfo() {
        return `${this.name} (${this.type})`;
    }
}

class ItemDisplay {
    // This constructor takes the entire GameItem object, making it tightly coupled.
    constructor(gameItem) {
        this.gameItem = gameItem; // Stores a reference to the GameItem instance
    }

    renderIcon() {
        // Accesses iconUrl and name directly from the stored GameItem.
        // This means GameItem still needs to hold display-specific data (iconUrl).
        return `<img src="${this.gameItem.iconUrl}" alt="${this.gameItem.name}">`;
    }

    getDisplayDescription() {
        // Accesses type and name directly from the stored GameItem.
        return `A rare ${this.gameItem.type} named ${this.gameItem.name}.`;
    }
}

// Example usage
const sword = new GameItem('s123', 'Excalibur', 'Legendary Sword', '/icons/sword.png');
const swordDisplay = new ItemDisplay(sword); // Pass the whole GameItem instance

console.log(sword.getInfo());
console.log(swordDisplay.renderIcon());
console.log(swordDisplay.getDisplayDescription());

